    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalLength = scanner.nextInt();
        String document = scanner.next();
        scanner.close();

        int maxOutsideSegment = 0, maxInsideSegment = 0, outsideCounter = 0, insideCounter = 0;
        boolean insideParentheses = false;

        for (int index = 0; index < totalLength; index++) {
            char ch = document.charAt(index);
            if (ch == '(') {
                insideParentheses = true;
                insideCounter = 0;
            } else if (ch == ')') {
                insideParentheses = false;
            } else if (insideParentheses) {
                if (ch != '_' && ch != '(' && ch != ')') {
                    insideCounter++;
                }
            } else {
                if (ch != '_' && ch != '(' && ch != ')') {
                    outsideCounter++;
                } else {
                    if (outsideCounter > maxOutsideSegment) {
                        maxOutsideSegment = outsideCounter;
                    }
                    outsideCounter = 0;
                }
            }
        }
        if (outsideCounter > maxOutsideSegment) {
            maxOutsideSegment = outsideCounter;
        }

        System.out.println(maxOutsideSegment + " " + insideCounter);
    }
}
